package net.civeira.phylax.feature.observe.observedprobe.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ExpectedStatusVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property expected status of observed probe ")
  void test_expected_status_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> ExpectedStatusVO.tryFrom(null));
    Assertions.assertEquals(1, ExpectedStatusVO.from(1).getExpectedStatus());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> ExpectedStatusVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", ExpectedStatusVO.from(1).toString());
  }
}
